  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Tiege Hanley Affiliate Program (via Refersion)', 'https://tiegehanley.refersion.com', 'https://tiegehanley.refersion.com', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://tiegehanley.refersion.com', 'official_program_terms', 'affiliate_program_terms', 'Tiege Hanley''s own Refersion program agreement (fetched 2026-11-21) confirms an open affiliate program: commission is a percentage of the purchase price (excluding tax and shipping) on a referred customer''s first purchase within 14 days of clicking the affiliate link, plus a $50 content usage payment the first time the brand uses a creator''s content in paid usage. The percentage itself is set in the program description rather than the agreement. The agreement states no earnings cap and no creator count, so cap and saturation are recorded unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://tiegehanley.refersion.com', 'third_party_listing', 'commission_rate_conflict', 'Third-party sources conflict on the rate: a getsaral case study reports affiliates earning 20% commission, while Lasso''s directory lists ''up to 15%''. Because the brand''s own program materials do not publish a single rate, commission_rate is recorded null.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 10, 10, 8, 4, '{"niche_fit": "Men''s skincare is a growing creator niche and Tiege Hanley is one of its anchor DTC brands.", "ugc_evidence": "The program terms build in paid content usage ($50 first paid use) and the brand also runs TikTok Shop and Shop app creator channels, per its own affiliate page.", "compensation": "Rate not recorded: third-party sources conflict (20% in a case study vs up to 15% in a directory) and the brand''s own terms set the percentage privately. No cap statement published \u2014 cap unknown.", "contact_access": "Public Refersion application portal plus a dedicated affiliate page on the brand''s own site.", "opportunity_availability": "Open application via Refersion, subject to brand approval.", "credibility": "Established US men''s skincare company selling DTC since 2016 with national name recognition."}'::jsonb);
