  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://freskincare.refersion.com', 'official_program_terms', 'affiliate_program_terms', 'FRÉ Skincare''s own Refersion affiliate agreement (fetched 2026-11-21) confirms an open affiliate program run by FRÉ Skincare Ltd.: commission is a fixed percentage of net receipts on qualified purchases, paid monthly by wire, check or PayPal. The percentage is conveyed to affiliates in writing rather than published, and affiliates must post about the brand on Instagram at least once a month, with the brand retaining perpetual rights to affiliate content. The agreement states no earnings cap and no creator count, so the rate is recorded null and cap and saturation unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 9, 9, 7, 4, '{"niche_fit": "Facial skincare sold DTC \u2014 in-niche, with an active-lifestyle angle that suits fitness-beauty crossover creators.", "ugc_evidence": "The program is built around creator content: affiliates must post on Instagram monthly and the brand licenses affiliate content for its own channels in perpetuity.", "compensation": "Commission is a percentage of net receipts paid monthly, but the percentage is not published (conveyed privately to accepted affiliates), so the rate is recorded null. No cap statement published \u2014 cap unknown.", "contact_access": "Public Refersion application portal run by the brand itself.", "opportunity_availability": "Open application, but acceptance is at the brand''s sole discretion and rejected applicants may not re-apply without consent.", "credibility": "Operating DTC skincare brand (FR\u00c9 Skincare Ltd.) with a formal, published affiliate agreement."}'::jsonb);
