  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'http://help.luggagehero.com/en/articles/13570862-commission-tiers-bonus-opportunities', 'official_site', 'compensation', 'LuggageHero''s own help center documents the tiers on top of the 10% default: 15% at 200+ qualified clicks per month, 20% at 500+, plus a +5% bonus for qualifying blog content, with support at affiliate@luggagehero.com.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 11, 15, 12, 8, 4, '{"compensation": "A verified 10% standard commission on Awin, with the brand''s own help center documenting tiers up to 20% plus a blog-content bonus - the strongest published pay in this group.", "contact_access": "Two published affiliate contacts: a named affiliate team email on the Awin profile and a support email in the brand''s own help center.", "credibility": "Operating in 210 cities across 53 countries with 1,000+ storage locations, though a smaller brand than the major travel platforms.", "niche_fit": "Luggage storage is a practical travel-hack topic that fits travel creator content well, though it is a utility service rather than an aspirational product.", "opportunity_availability": "Open application through Awin''s US program with standard network approval.", "ugc_evidence": "The program explicitly rewards blog content with a commission bonus and targets travel bloggers and content sites, but runs no formal ambassador cohort."}'::jsonb);
