  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.iconically.com/stay22-campaign-1386.html', 'listing', 'affiliate', 'Stay22''s creator campaign page describes it as the monetization layer behind 5,000+ creators and publishers driving over $1B in annual travel bookings through partners like Booking.com, Expedia, Hotels.com, GetYourGuide, Agoda and Kayak; commissions start at 30%, there is no cost to join and no follower or traffic minimum, and links can be dropped into Instagram bios, TikTok captions, YouTube descriptions, blogs and newsletters.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.travelinmypocket.com/stay22-review/', 'listing', 'compensation', 'Stay22 operates on a revenue-share model: the publisher''s share starts at 30% of the commission Stay22 itself receives from the booking partner (reported as negotiable up to 80% at volume). The 30% figure recorded is that revenue-share percentage, not a percentage of booking value, so effective earnings per booking vary by partner.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 12, 6, 9, 4, '{"compensation": "A published 30% starting revenue share of the commission Stay22 receives - meaningful pay, but it is a share of commission rather than of booking value, so effective rates vary by partner.", "contact_access": "Sign-up is self-serve on the platform; no public partnerships email was verified.", "credibility": "Established travel-tech platform reporting $1B in annual partner bookings, though smaller than the OTAs it aggregates.", "niche_fit": "Built specifically to monetize travel content across Instagram, TikTok, YouTube and blogs - a near-perfect fit for travel creators.", "opportunity_availability": "Free to join with no follower or traffic minimum - the most open availability in this group.", "ugc_evidence": "The platform is creator-first by design (5,000+ creators and publishers, tools that monetize existing social and blog content), though that scale also means saturation is not low."}'::jsonb);
